package censusfixture

import (
    "encoding/json"
    "os"
)

type Route struct {
    Prefix string `json:"prefix"`
    Installed bool `json:"installed"`
}

func PublishRoutes(path string, routes []Route) error {
    body, err := json.Marshal(struct { Routes []Route `json:"routes"` }{Routes: routes})
    if err != nil { return err }
    return os.WriteFile(path, body, 0600)
}

